def followup_view(inputs, prior):
    packet=inputs.get('twentyfirst_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('twentyfirst period packet changed')
    if prior is None or prior['counts']['after']!=126 or packet['prior_digest']!=digest(prior):raise ValueError('twentyfirst period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('twentyfirst period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=25 or len(packet['sources'])!=25 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('twentyfirst period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('twentyfirst period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('twentyfirst period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('twentyfirst period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('twentyfirst period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('twentyfirst period page changed')
    for row in FINANCIAL:
        h,old,nine=D(row['h1_yuan']),D(row['prior_h1_yuan']),D(row['nine_month_yuan'])
        yoy=((h-old)/abs(old)*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if row['h1_yoy_pct'] is not None and yoy!=D(row['h1_yoy_pct']):raise ValueError('twentyfirst period H1 arithmetic changed')
        if row['reported_h1_yoy_pct']is not None and yoy!=D(row['reported_h1_yoy_pct']):raise ValueError('twentyfirst period reported H1 changed')
        if nine-h!=D(row['quarter_yuan']):raise ValueError('twentyfirst period quarter changed')
        if row['reported_quarter_yuan']is not None:
            delta=nine-h-D(row['reported_quarter_yuan'])
            if delta!=D(row['quarter_difference_yuan']):raise ValueError('twentyfirst period preserved quarter difference changed')
            expected='direct_and_difference_checked'if delta==0 else 'reported_and_difference_conflict'
            if row['quarter_basis']!=expected:raise ValueError('twentyfirst period quarter label changed')
        elif row['quarter_basis']!='nine_month_minus_h1':raise ValueError('twentyfirst period derived quarter label changed')
        for aid,n,keys in [(row['h1_source'],row['h1_page'],['h1_yuan','prior_h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan']+(['reported_quarter_yuan']if row['reported_quarter_yuan']is not None else []))]:
            text=sources[aid]['selected_pages'][str(n)].replace(',','').replace('\n','').replace(' ','').replace('−','-')
            if any(row[k]not in text for k in keys):raise ValueError('twentyfirst period financial source changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('twentyfirst period windows changed')
    conflicts=[(r['symbol'],r['metric'],r['quarter_difference_yuan'])for r in FINANCIAL if r['quarter_basis']=='reported_and_difference_conflict']
    if conflicts!=[]:raise ValueError('twentyfirst preserved financial difference changed')
    result={'through': '2026-11-19', 'title': '利润、整改与回款分别改善了什么？', 'answer': '海钦利润增长与单季经营现金流出并存，旧处罚和新监管分列；洲际补充审议完成不代替独立审计验证。中路仍有798万元占款未收，诉讼和股东清算不当回款；京化单季归母下降与扣非增长并存，先核重述及非经常性损益。', 'counts': {'files': 25, 'new_files': 25, 'reused_files': 0, 'pages': 824, 'new_pages': 824, 'viewed_pages': 18, 'initial_coverage': 126, 'complete_windows': 68, 'unfinished_windows': 7, 'stock_endpoint_gaps': 0}, 'boundary': '138条目录，25份824页中核18关键页，不认证全文或全部催化。75窗口68满7未满，72个股票端点跨渠道核；52共同阶段。16项季度桥接含15直接、1现金派生；11项半年同比与原表一致，5项不适用保留。披露仅精确到日期，不能作公告净影响；重复月报不算独立案例，不晋级通用经验。', 'method_promotions': 0}
    result.update(chains=CHAINS,financial_bridge=FINANCIAL,phase_comparisons=PHASES,event_windows=windows,sources=[{k:v for k,v in s.items()if k not in ["raw_item","selected_pages","page_hashes"]}for s in sources.values()])
    return result
